-- dbo.fOrderTotal: Definition differs
GO
CREATE OR ALTER FUNCTION dbo.fOrderTotal (@CustomerId int)
RETURNS decimal(18,2)
AS
BEGIN
    RETURN (SELECT SUM(Amount) FROM dbo.Orders WHERE CustomerId = @CustomerId);
END;

GO

